'use client';

import React from 'react';
import { Plus, Trash2, Filter } from 'lucide-react';
import {
    SegmentRule,
    SegmentField,
    SegmentOperator,
    SegmentRulesPayload,
} from '../types/campaign.types';

// ============================================================================
// FIELD / OPERATOR DEFINITIONS
// ============================================================================

const FIELDS: { value: SegmentField; label: string }[] = [
    { value: 'last_order', label: 'Last Order (days ago)' },
    { value: 'total_spend', label: 'Total Spend' },
    { value: 'orders_count', label: 'Orders Count' },
    { value: 'store', label: 'Store' },
    { value: 'consent_status', label: 'Consent Status' },
];

const OPERATORS: { value: SegmentOperator; label: string }[] = [
    { value: '>', label: 'greater than' },
    { value: '<', label: 'less than' },
    { value: '=', label: 'equals' },
    { value: 'contains', label: 'contains' },
];

function generateId(): string {
    return Math.random().toString(36).substring(2, 9);
}

function createEmptyRule(): SegmentRule {
    return { id: generateId(), field: 'last_order', operator: '>', value: '' };
}

// ============================================================================
// COMPONENT
// ============================================================================

interface SegmentRuleBuilderProps {
    value: SegmentRulesPayload;
    onChange: (payload: SegmentRulesPayload) => void;
}

export const SegmentRuleBuilder: React.FC<SegmentRuleBuilderProps> = ({ value, onChange }) => {
    const { logic, rules } = value;

    const updateRule = (id: string, patch: Partial<SegmentRule>) => {
        onChange({
            ...value,
            rules: rules.map((r) => (r.id === id ? { ...r, ...patch } : r)),
        });
    };

    const addRule = () => {
        onChange({ ...value, rules: [...rules, createEmptyRule()] });
    };

    const removeRule = (id: string) => {
        onChange({ ...value, rules: rules.filter((r) => r.id !== id) });
    };

    const toggleLogic = () => {
        onChange({ ...value, logic: logic === 'AND' ? 'OR' : 'AND' });
    };

    return (
        <div className="space-y-4">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Filter className="w-4 h-4 text-indigo-500" />
                    <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">
                        Segment Rules
                    </h3>
                </div>
                <span className="text-[10px] font-bold px-2 py-0.5 bg-slate-100 text-slate-500 rounded-full">
                    {rules.length} rule{rules.length !== 1 ? 's' : ''}
                </span>
            </div>

            {/* Logic Toggle */}
            {rules.length > 1 && (
                <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        Match
                    </span>
                    <button
                        onClick={toggleLogic}
                        className={`relative px-1 py-0.5 rounded-lg border text-xs font-black uppercase tracking-wider transition-all duration-200 flex overflow-hidden
                            ${logic === 'AND'
                                ? 'bg-indigo-50 border-indigo-200 text-indigo-700'
                                : 'bg-amber-50 border-amber-200 text-amber-700'
                            }`}
                    >
                        <span className={`px-2.5 py-1 rounded-md transition-all duration-200 ${logic === 'AND' ? 'bg-indigo-600 text-white shadow-sm' : ''}`}>
                            AND
                        </span>
                        <span className={`px-2.5 py-1 rounded-md transition-all duration-200 ${logic === 'OR' ? 'bg-amber-500 text-white shadow-sm' : ''}`}>
                            OR
                        </span>
                    </button>
                    <span className="text-[10px] text-slate-400">
                        {logic === 'AND' ? 'all rules must match' : 'any rule can match'}
                    </span>
                </div>
            )}

            {/* Rules */}
            <div className="space-y-2">
                {rules.map((rule, idx) => (
                    <div key={rule.id} className="group">
                        {/* Logic connector between rules */}
                        {idx > 0 && (
                            <div className="flex items-center gap-2 py-1.5 pl-4">
                                <div className="w-px h-3 bg-slate-200" />
                                <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full
                                    ${logic === 'AND' ? 'bg-indigo-50 text-indigo-600' : 'bg-amber-50 text-amber-600'}`}>
                                    {logic}
                                </span>
                                <div className="flex-1 h-px bg-slate-100" />
                            </div>
                        )}

                        {/* Rule row */}
                        <div className="flex items-center gap-2 p-3 bg-white border border-slate-200 rounded-xl hover:border-indigo-200 transition-colors">
                            {/* Field */}
                            <select
                                value={rule.field}
                                onChange={(e) => updateRule(rule.id, { field: e.target.value as SegmentField })}
                                className="flex-1 min-w-0 px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-800 focus:border-indigo-500 outline-none transition-all"
                            >
                                {FIELDS.map((f) => (
                                    <option key={f.value} value={f.value}>{f.label}</option>
                                ))}
                            </select>

                            {/* Operator */}
                            <select
                                value={rule.operator}
                                onChange={(e) => updateRule(rule.id, { operator: e.target.value as SegmentOperator })}
                                className="w-[130px] shrink-0 px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-800 focus:border-indigo-500 outline-none transition-all"
                            >
                                {OPERATORS.map((o) => (
                                    <option key={o.value} value={o.value}>{o.label}</option>
                                ))}
                            </select>

                            {/* Value */}
                            <input
                                type="text"
                                value={rule.value}
                                onChange={(e) => updateRule(rule.id, { value: e.target.value })}
                                placeholder="Value"
                                className="w-[120px] shrink-0 px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-800 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-300"
                            />

                            {/* Delete */}
                            <button
                                onClick={() => removeRule(rule.id)}
                                disabled={rules.length <= 1}
                                className="p-2 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-all disabled:opacity-0 disabled:cursor-default"
                                title="Remove rule"
                            >
                                <Trash2 className="w-3.5 h-3.5" />
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            {/* Add Rule */}
            <button
                onClick={addRule}
                className="flex items-center gap-2 px-4 py-2.5 w-full justify-center border-2 border-dashed border-slate-200 rounded-xl text-xs font-bold text-slate-500 uppercase tracking-wider hover:border-indigo-300 hover:text-indigo-600 hover:bg-indigo-50/50 transition-all"
            >
                <Plus className="w-3.5 h-3.5" /> Add Rule
            </button>

            {/* JSON Preview (collapsed) */}
            {rules.length > 0 && rules.some(r => r.value) && (
                <details className="group">
                    <summary className="text-[10px] font-bold text-slate-400 uppercase tracking-widest cursor-pointer hover:text-indigo-500 transition-colors">
                        Preview JSON output
                    </summary>
                    <pre className="mt-2 p-4 bg-slate-900 text-emerald-400 rounded-xl text-xs overflow-x-auto font-mono leading-relaxed">
                        {JSON.stringify(value, null, 2)}
                    </pre>
                </details>
            )}
        </div>
    );
};

export default SegmentRuleBuilder;
